export function SpendForm({ group, forceApproval, onDone }: { group: Group, forceApproval: boolean, onDone: () => void }) {
  const { getAccessToken, user } = usePrivy();
  const { wallets } = useWallets();
  const embeddedWallet = wallets.find((w) => w.walletClientType === "privy");

  const [amount, setAmount] = useState("");
  const [desc, setDesc] = useState("");
  const [cvu, setCvu] = useState("");
  const [error, setError] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async () => {
    if (!amount || Number(amount) <= 0) return setError("Ingresa un monto válido");
    if (!cvu.trim()) return setError("El Alias o CVU es requerido");
    if (!desc.trim()) return setError("La descripción es requerida");
    if (!embeddedWallet) return setError("Wallet no conectada");

    setIsSubmitting(true);
    setError("");
    try {
      const token = await getAccessToken();
      const { nonce } = await api.getNonce(token!, group.id);

      const monAmountStr = fiatToMon(Number(amount)).toString();
      const signature = await signTyped(
        embeddedWallet,
        "RequestExpense",
        group.contractAddress,
        { user: user?.wallet?.address || "", amount: toWei(monAmountStr), desc, forceApproval, nonce: BigInt(nonce) }
      );

